"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { type AgentTask, SEED_TASKS, type TaskAction } from "./agent-tasks/data";
import { TaskCard } from "./agent-tasks/task-card";
import { type NewTask, TaskComposer } from "./agent-tasks/task-composer";
import { readTask, type TaskStatus } from "./agent-tasks/task-state";
import { useInterval } from "./lib/timers";

type Filter = "all" | "running" | "ready" | "merged";

const FILTERS: { value: Filter; label: string }[] = [
  { value: "all", label: "All" },
  { value: "running", label: "Running" },
  { value: "ready", label: "Ready for review" },
  { value: "merged", label: "Merged" },
];

const MATCH = {
  all: () => true,
  running: (status: TaskStatus) => status === "queued" || status === "running",
  ready: (status: TaskStatus) => status === "ready",
  merged: (status: TaskStatus) => status === "merged",
} satisfies Record<Filter, (status: TaskStatus) => boolean>;

// Critically damped: 2 * sqrt(420) is about 41.
const GROW = { type: "spring", stiffness: 420, damping: 41, mass: 1 } as const;

/**
 * A home for background coding agents. Describe a task, pick where it runs,
 * and start it: the card grows in at the top, waits in the queue, walks its
 * steps, then offers a pull request with the change it made.
 */
export function AgentTasks({ className }: { className?: string }) {
  const titleId = useId();
  const reduceMotion = useReducedMotion();
  const [tasks, setTasks] = useState<AgentTask[]>(SEED_TASKS);
  const [now, setNow] = useState(0);
  const [fresh, setFresh] = useState<string | null>(null);
  const [openIds, setOpenIds] = useState<string[]>([]);
  const [filter, setFilter] = useState<Filter>("all");

  const readings = tasks.map((task) => ({ task, reading: readTask(task, now) }));
  const live = readings.some(({ reading }) => reading.status === "queued" || reading.status === "running");
  useInterval(() => setNow((tick) => tick + 1), live ? 500 : null);

  const counts = Object.fromEntries(
    FILTERS.map(({ value }) => [value, readings.filter(({ reading }) => MATCH[value](reading.status)).length]),
  );
  const shown = readings.filter(({ reading }) => MATCH[filter](reading.status));

  const start = (draft: NewTask) => {
    const id = `task-${now}-${tasks.length}`;
    const seed = draft.title.length;
    setTasks((current) => [
      {
        id,
        ...draft,
        startedAt: now,
        action: "none",
        added: 24 + ((seed * 7) % 90),
        removed: 3 + (seed % 17),
        files: 2 + (seed % 5),
        checks: 18 + (seed % 9),
        pullRequest: 612 + tasks.length,
      },
      ...current,
    ]);
    setFresh(id);
    if (filter === "merged" || filter === "ready") setFilter("all");
  };

  const act = (id: string, action: TaskAction) =>
    setTasks((current) =>
      current.map((task) => (task.id === id ? { ...task, action, stoppedAt: action === "cancelled" ? now : task.stoppedAt } : task)),
    );

  const toggle = (id: string) => setOpenIds((current) => (current.includes(id) ? current.filter((item) => item !== id) : [...current, id]));

  return (
    <BlockFrame aria-labelledby={titleId} className={cn("mx-auto max-w-3xl", className)}>
      <header className="flex flex-col gap-1 border-b border-border px-5 py-4">
        <h2 id={titleId} className="text-base font-semibold">
          Background tasks
        </h2>
        <p className="text-sm text-muted-foreground">Agents work on Fernhill code while you do something else.</p>
      </header>

      <div className="flex flex-col gap-4 p-5">
        <TaskComposer onStart={start} />

        <div className="-mx-1 overflow-x-auto scroll-fade-effect-x scrollbar-none px-1 py-1">
          <SegmentedControl
            aria-label="Show tasks"
            value={filter}
            onValueChange={setFilter}
            options={FILTERS.map(({ value, label }) => ({
              value,
              label: (
                <span className="inline-flex items-center gap-1.5 whitespace-nowrap">
                  {label}
                  <span className="text-xs tabular-nums text-muted-foreground">{counts[value]}</span>
                </span>
              ),
            }))}
          />
        </div>

        <p role="status" className="sr-only">
          {counts.running} running, {counts.ready} ready for review, {counts.merged} merged.
        </p>

        <ul aria-label="Tasks" className="flex flex-col">
          <AnimatePresence initial={false}>
            {shown.map(({ task, reading }) => (
              <motion.li
                key={task.id}
                layout={reduceMotion ? false : "position"}
                initial={reduceMotion ? false : { height: 0, opacity: 0 }}
                animate={{ height: "auto", opacity: 1 }}
                exit={reduceMotion ? { opacity: 0, transition: { duration: 0 } } : { height: 0, opacity: 0 }}
                transition={reduceMotion ? { duration: 0 } : { height: GROW, layout: GROW, opacity: { duration: 0.18 } }}
                className="overflow-hidden"
              >
                <div className="pb-2">
                  <TaskCard
                    task={task}
                    reading={reading}
                    fresh={task.id === fresh}
                    open={openIds.includes(task.id)}
                    onToggle={() => toggle(task.id)}
                    onCancel={() => act(task.id, "cancelled")}
                    onPullRequest={() => act(task.id, "pr")}
                    onMerge={() => act(task.id, "merged")}
                  />
                </div>
              </motion.li>
            ))}
          </AnimatePresence>
          {shown.length === 0 ? <li className="py-6 text-center text-sm text-muted-foreground">No tasks here yet.</li> : null}
        </ul>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

/** A choice a person makes for a new task. */
export interface Choice {
  value: string;
  label: string;
}

/** The Fernhill repositories an agent can work in. */
export const REPOS: Choice[] = [
  { value: "booking-web", label: "fernhill/booking-web" },
  { value: "clinic-api", label: "fernhill/clinic-api" },
  { value: "reminders", label: "fernhill/reminders" },
];

/** The branches a task can start from. */
export const BRANCHES: Choice[] = [
  { value: "main", label: "main" },
  { value: "release-4.2", label: "release-4.2" },
];

/** The invented models a task can run on. */
export const MODELS: Choice[] = [
  { value: "larch-2", label: "Larch 2" },
  { value: "larch-2-mini", label: "Larch 2 mini" },
];

/** The steps every running task walks through, in order. */
export const TASK_STEPS = ["Reading the code", "Planning the change", "Editing files", "Running the tests"];

/** Half-second ticks a new task waits in the queue. */
export const QUEUE_TICKS = 4;
/** Half-second ticks each running step takes. */
export const STEP_TICKS = 5;

/** What a person did to a task. A task with no action follows its timer. */
export type TaskAction = "none" | "cancelled" | "pr" | "merged";

/** One background task. */
export interface AgentTask {
  id: string;
  title: string;
  repo: string;
  branch: string;
  model: string;
  /** The tick the task started on. Older seed tasks start far in the past, so they are already ready. */
  startedAt: number;
  action: TaskAction;
  /** The tick a person cancelled the task on, so its clock stops there. */
  stoppedAt?: number;
  /** The change once ready. */
  added: number;
  removed: number;
  files: number;
  checks: number;
  pullRequest: number;
}

/** The tasks on the page when it opens. */
export const SEED_TASKS: AgentTask[] = [
  {
    id: "seed-1",
    title: "Send a text reminder 24 hours before each visit",
    repo: "fernhill/reminders",
    branch: "main",
    model: "Larch 2",
    startedAt: -9,
    action: "none",
    added: 96,
    removed: 12,
    files: 4,
    checks: 22,
    pullRequest: 611,
  },
  {
    id: "seed-2",
    title: "Let practitioners block out lunch on the rota",
    repo: "fernhill/booking-web",
    branch: "main",
    model: "Larch 2 mini",
    startedAt: -160,
    action: "none",
    added: 142,
    removed: 18,
    files: 6,
    checks: 24,
    pullRequest: 608,
  },
  {
    id: "seed-3",
    title: "Fix the double booking when two rooms share a slot",
    repo: "fernhill/clinic-api",
    branch: "release-4.2",
    model: "Larch 2",
    startedAt: -420,
    action: "merged",
    added: 38,
    removed: 21,
    files: 3,
    checks: 19,
    pullRequest: 597,
  },
];

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId } from "react";

import { CheckIcon, ChevronRightIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { MergeIcon, BranchIcon } from "../icons";
import { formatSeconds } from "../lib/format";
import { Reveal } from "../parts/reveal";
import { type AgentTask, TASK_STEPS } from "./data";
import { StatusLine } from "./status-line";
import type { TaskReading } from "./task-state";

/** Props for one background task. */
export interface TaskCardProps {
  task: AgentTask;
  reading: TaskReading;
  /** True for a task a person just started: its background flashes the accent once. */
  fresh: boolean;
  open: boolean;
  onToggle: () => void;
  onCancel: () => void;
  onPullRequest: () => void;
  onMerge: () => void;
}

/**
 * One task: its title, where it runs, how long it has run, a status line and
 * the action that fits its state. The toggle opens the step log.
 */
export function TaskCard({ task, reading, fresh, open, onToggle, onCancel, onPullRequest, onMerge }: TaskCardProps) {
  const reduceMotion = useReducedMotion();
  const logId = useId();
  const { status, step } = reading;
  const finished = status === "ready" || status === "merged";

  return (
    <article aria-label={task.title} className="relative isolate overflow-hidden rounded-xl border border-border">
      {fresh && !reduceMotion ? (
        <motion.span
          aria-hidden="true"
          initial={{ opacity: 1 }}
          animate={{ opacity: 0 }}
          transition={{ duration: 1.4, ease: "easeOut" }}
          className="absolute inset-0 -z-10 bg-chart-1/15"
        />
      ) : null}
      <div className="flex flex-col gap-3 p-3 @lg:flex-row @lg:items-center">
        <div className="flex min-w-0 flex-1 items-start gap-2">
          <Button
            variant="ghost"
            size="icon"
            aria-expanded={open}
            aria-controls={logId}
            aria-label={`Steps for ${task.title}`}
            onClick={onToggle}
            className="size-7 shrink-0"
          >
            <ChevronRightIcon aria-hidden="true" className={cn("size-4 motion-safe:transition-transform", open && "rotate-90")} />
          </Button>
          <div className="flex min-w-0 flex-col gap-1">
            <h3 className="text-sm font-medium">{task.title}</h3>
            <p className="flex flex-wrap items-center gap-x-3 gap-y-0.5 text-xs text-muted-foreground">
              <span className="font-mono">{task.repo}</span>
              <span className="inline-flex items-center gap-1">
                <BranchIcon aria-hidden="true" className="size-3" />
                {task.branch}
              </span>
              <span>{task.model}</span>
              <span className="tabular-nums">{formatSeconds(reading.seconds)}</span>
            </p>
            <div className="relative grid min-h-5 text-xs">
              <AnimatePresence initial={false} mode="popLayout">
                <motion.p
                  key={`${status}-${step}-${task.action}`}
                  initial={reduceMotion ? false : { opacity: 0, y: 4 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: reduceMotion ? 0 : -4 }}
                  transition={{ duration: reduceMotion ? 0 : 0.2 }}
                  className="col-start-1 row-start-1 flex flex-wrap items-center gap-x-2 gap-y-0.5"
                >
                  <StatusLine task={task} reading={reading} />
                </motion.p>
              </AnimatePresence>
            </div>
          </div>
        </div>
        <div className="flex shrink-0 justify-end gap-2 pl-9 @lg:pl-0">
          {status === "queued" || status === "running" ? (
            <Button variant="outline" size="sm" onClick={onCancel}>
              Cancel
            </Button>
          ) : null}
          {status === "ready" && task.action !== "pr" ? (
            <Button size="sm" onClick={onPullRequest}>
              <MergeIcon aria-hidden="true" className="size-3.5" />
              Create pull request
            </Button>
          ) : null}
          {status === "ready" && task.action === "pr" ? (
            <Button size="sm" variant="secondary" onClick={onMerge}>
              Merge
            </Button>
          ) : null}
        </div>
      </div>
      <Reveal open={open} id={logId} className="border-t border-border px-3 py-2 pl-12">
        <ol aria-label="Steps" className="flex flex-col gap-1.5 text-xs">
          {TASK_STEPS.map((label, index) => {
            const doneStep = finished || (status === "running" && index < step);
            const live = status === "running" && index === step;
            return (
              <li key={label} className="flex items-center gap-2">
                {doneStep ? (
                  <CheckIcon aria-hidden="true" className="size-3.5 text-marketing-green-ink" />
                ) : (
                  <span aria-hidden="true" className={cn("mx-1 size-1.5 rounded-full", live ? "bg-chart-1" : "bg-border")} />
                )}
                <span className={doneStep || live ? "text-foreground" : "text-muted-foreground"}>{label}</span>
                <span className="sr-only">{doneStep ? ", done" : live ? ", in progress" : ", not started"}</span>
              </li>
            );
          })}
        </ol>
      </Reveal>
    </article>
  );
}

