  reading: TaskReading;
}

/** The words for where a task stands: queued, the live step, the change it made, or how it ended. */
export function StatusLine({ task, reading }: StatusLineProps) {
  switch (reading.status) {
    case "queued":
      return (
        <span className="inline-flex items-center gap-1.5 text-muted-foreground">
          <HourglassIcon aria-hidden="true" className="size-3.5" />
          Waiting in the queue
        </span>
      );
    case "running":
      return <ShimmerText text={`${TASK_STEPS[reading.step] ?? "Working"}`} active />;
    case "cancelled":
      return (
        <span className="inline-flex items-center gap-1.5 text-muted-foreground">
          <CircleXIcon aria-hidden="true" className="size-3.5" />
          Cancelled, no changes kept
        </span>
      );
    case "merged":
      return (
        <span className="inline-flex items-center gap-1.5 text-muted-foreground">
          <MergeIcon aria-hidden="true" className="size-3.5 text-chart-4" />
          Merged as pull request {task.pullRequest}
        </span>
      );
