import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for a line of text that shimmers while its work runs. */
export interface ShimmerTextProps {
  text: string;
  /** The text shimmers only while this is true. */
  active: boolean;
  className?: string;
}

/**
 * A short line, such as the verb of a running step, with a light band that
 * sweeps across it while `active` is true. With reduced motion the text stays still.
 */
export function ShimmerText({ text, active, className }: ShimmerTextProps) {
  const reduceMotion = useReducedMotion();
  if (!active || reduceMotion) return <span className={className}>{text}</span>;
  return (
    <motion.span
      className={cn(
        "bg-linear-to-r from-muted-foreground via-foreground to-muted-foreground bg-size-(--shimmer) bg-clip-text text-transparent",
        className,
      )}
      style={
        // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
        { "--shimmer": "200% 100%" } as VarStyle
      }
      initial={{ backgroundPosition: "100% 0" }}
      animate={{ backgroundPosition: "-100% 0" }}
      transition={{ duration: 1.6, ease: "linear", repeat: Infinity }}
    >
      {text}
    </motion.span>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

import { type AgentTask, QUEUE_TICKS, STEP_TICKS, TASK_STEPS } from "./data";

/** Where a task stands now. */
export type TaskStatus = "queued" | "running" | "ready" | "cancelled" | "merged";

/** A task's status, its live step and how long it has run, read from the clock. */
export interface TaskReading {
  status: TaskStatus;
  /** The index of the live step while running, else -1. */
  step: number;
  /** Seconds the task has run. The clock stops when the task is ready, cancelled or merged. */
  seconds: number;
}

const FINISH = QUEUE_TICKS + TASK_STEPS.length * STEP_TICKS;

/** Reads a task at tick `now`. Everything follows from its start tick and what a person did to it. */
export function readTask(task: AgentTask, now: number): TaskReading {
  const age = now - task.startedAt;
  if (task.action === "cancelled") {
    const stopped = (task.stoppedAt ?? now) - task.startedAt;
    return { status: "cancelled", step: -1, seconds: stopped / 2 };
  }
  if (task.action === "merged") return { status: "merged", step: -1, seconds: FINISH / 2 };
  if (age >= FINISH || task.action === "pr") return { status: "ready", step: -1, seconds: FINISH / 2 };
  if (age < QUEUE_TICKS) return { status: "queued", step: -1, seconds: age / 2 };
  return { status: "running", step: Math.floor((age - QUEUE_TICKS) / STEP_TICKS), seconds: age / 2 };
}

