import { BranchIcon, CodeIcon, PlayIcon } from "../icons";
import { ChoiceChip } from "./choice-chip";
import { BRANCHES, MODELS, REPOS } from "./data";

/** What a person asked for when they start a task. */
export interface NewTask {
  title: string;
  repo: string;
  branch: string;
  model: string;
}

/** Props for the field that starts a task. */
export interface TaskComposerProps {
  onStart: (task: NewTask) => void;
}

/**
 * A field to describe a task, chips for repository, branch and model, and a
 * Start button. Command or Control with Enter starts the task from the field.
 */
export function TaskComposer({ onStart }: TaskComposerProps) {
  const fieldId = useId();
  const [text, setText] = useState("");
  const [repo, setRepo] = useState(REPOS[0]?.value ?? "");
  const [branch, setBranch] = useState(BRANCHES[0]?.value ?? "");
  const [model, setModel] = useState(MODELS[0]?.value ?? "");
  const ready = text.trim().length > 0;

  const start = () => {
    if (!ready) return;
    onStart({
      title: text.trim(),
      repo: REPOS.find((item) => item.value === repo)?.label ?? repo,
      branch,
      model: MODELS.find((item) => item.value === model)?.label ?? model,
    });
    setText("");
  };

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        start();
      }}
      className="flex flex-col gap-3"
    >
      <label htmlFor={fieldId} className="sr-only">
        Describe a task for the agent
      </label>
      <Textarea
        id={fieldId}
        value={text}
        onChange={(event) => setText(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
            event.preventDefault();
            start();
          }
        }}
        aria-keyshortcuts="Meta+Enter Control+Enter"
        placeholder="Describe a task, such as: add a cancel link to the booking email"
      />
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex min-w-0 flex-wrap gap-2">
          <ChoiceChip label="Repository" icon={<CodeIcon aria-hidden="true" className="size-3.5" />} options={REPOS} value={repo} onValueChange={setRepo} />
          <ChoiceChip label="Branch" icon={<BranchIcon aria-hidden="true" className="size-3.5" />} options={BRANCHES} value={branch} onValueChange={setBranch} />
          <ChoiceChip label="Model" icon={<SparklesIcon aria-hidden="true" className="size-3.5" />} options={MODELS} value={model} onValueChange={setModel} />
        </div>
        <div className="ml-auto flex items-center gap-2">
          <Kbd aria-hidden="true" className="hidden @md:inline-flex">
            ⌘ Enter
          </Kbd>
          <Button type="submit" size="sm" disabled={!ready}>
            <PlayIcon aria-hidden="true" className="size-3.5" />
            Start
          </Button>
        </div>
      </div>
    </form>
  );
}

